INSERT INTO `v1_9008b10a959c26a63fa0014cf05cd58eaf59c0560ebf8cff128ab058de4b0ed7` VALUES ("加速の玉飾り", "不思議な効果を持つイヤリング。\n装備者に活力加速を与える。", 1, "ＴＰ上昇＋5", 11001, 1, 1, 11001);
